#!/data/data/com.termux/files/usr/bin/bash

_s(){
  local _tv
  _tv=$(grep "TracerPid" /proc/$$/status 2>/dev/null|awk '{print $2}')
  [ -n "$_tv" ]&&[ "$_tv" != "0" ]&&exit 1
  for _b in strace ltrace gdb frida-server r2 apktool jadx; do
    pgrep -x "$_b" >/dev/null 2>&1&&exit 1
  done
}
_s




